import sys

class Solution:
    def __init__(self, s):
        self.s = s
    def solve(self):
        l = len(self.s)
        if l % 2 == 0:
            return 'T'
        for i in range(1, l // 2 + 1):
            if self.s[i] == self.s[l - 1 - i]:
                continue
            return 'N'
        return 'T'
    def test(self):
        sol = Solution(sys.stdin.readline())
        print(sol.solve())

if __name__ == '__main__':
