    public int maxParenDepth(String s) {
	Stack<Character> stack = new Stack<Character>();
	int max = 0;
	int count = 0;
	for(char c : s.toCharArray()) {
	    if(c == '(')
		stack.push(c);
	    else if(c == ')') {
		if(!stack.isEmpty()) {
		    stack.pop();
		    count++;
		}
	    }
	}
	max = Math.max(max, count);
	return max;
    }
}

