class Solution:
    def readBinaryWatch(self, num: int) -> List[str]:
        def get_time(hour, minute):
            return 1 if (hour & ((1 << 4) - 1)) == hour and (minute & ((1 << 6) - 1)) == minute else 0

        def helper(remain, hour, minute):
            if remain == 0:
                return get_time(hour, minute)

            if hour >= 12 or minute >= 60: return 0

            res = 0
            if remain & 1:
                res += helper(remain - 1, hour + 1, minute)

            if remain & 2:
                res += helper(remain - 2, hour, minute + 1)
            return res

        res = []
        for h in range(12):
            for m in range(60):
                if helper(num - 2, h, m):
                    res.append('%s:%s' % (h, m))
        return res
