    */
    public int[] sumAndProduct(List<Integer> l) {
	int sum = 0;
	int product = 1;
	double avg = 0.0;
	for (int i: l) {
	    sum += i;
	    product *= i;
	    avg += i;
	}
	int[] res = new int[3];
	res[0] = sum;
	res[1] = product;
	res[2] = (int) Math.round(avg/l.size());
	return res;
    }

