    public boolean isOneEditAway(String word, String newWord) {
        if (Math.abs(word.length() - newWord.length()) > 1) {
            return false;
        }
        int i = 0, j = 0;
        while (i < word.length() && j < newWord.length()) {
            if (word.charAt(i)!= newWord.charAt(j)) {
                if (word.length() == newWord.length()) {
                    i++;
                } else {
                    j++;
                }
            } else {
                i++;
                j++;
            }
        }
        return i == word.length() && j == newWord.length() ||
                i == word.length() && j == newWord.length() - 1 ||
                i == word.length() - 1 && j == newWord.length();
    }

