public class Solution {
    public void merge(int A[], int m, int B[], int n) {
        if (n == 0) return;
        int[] combined = new int[m + n];
        int a = 0, b = 0;
        for (int i = 0; i < m + n; i++) {
            if (a == m) combined[i] = B[b++];
            else if (b == n) combined[i] = A[a++];
            else {
                if (A[a] < B[b]) combined[i] = A[a++];
                else combined[i] = B[b++];
            }
        }
        for (int i = 0; i < m + n; i++) A[i] = combined[i];
    }
