import java.util.*;

class Solution {
    public void recPerm(String s, String prefix, List<String> res) {
        if (s.length() == 0) {
            res.add(prefix);
            return;
        }
        for (int i = 0; i < s.length(); i++) {
            String remaining = s.substring(0, i) + s.substring(i + 1, s.length());
            recPerm(remaining, prefix + s.charAt(i), res);
        }
    }

    public List<String> permutation(String s) {
        List<String> res = new ArrayList<>();
        recPerm(s, "", res);
        return res;
    }
