    public String longestPalindrome(String s) {
        if (s.length() <= 1) {
            return s;
        }
        int begin = 0;
        int end = 0;
        int maxLen = 0;
        int len = s.length();
        for (int i = 0; i < len; i++) {
            int start = i;
            int end = i;
            while (start >= 0 && end < len && s.charAt(start) == s.charAt(end)) {
                int len = end - start + 1;
                if (len > maxLen) {
                    begin = start;
                    end = end;
                    maxLen = len;
                }
                start--;
                end++;
            }
            start = i;
            end = i + 1;
            while (start >= 0 && end < len && s.charAt(start) == s.charAt(end)) {
                int len = end - start + 1;
                if (len > maxLen) {
                    begin = start;
                    end = end;
                    maxLen = len;
                }
                start--;
                end++;
            }
        }
        return s.substring(begin, end);
    }

