class Solution69 {
    public int mySqrt(int x) {
        if (x == 0) {
            return 0;
        }
        int begin = 1;
        int end = x;
        while (begin <= end) {
            int mid = (begin + end) / 2;
            if (mid * mid == x) {
                return mid;
            } else if (mid * mid < x) {
                begin = mid + 1;
            } else {
                end = mid - 1;
            }
        }
        return end;
    }
