class Solution {
    public int wonderfulStrings(String word) {
        int MOD = 1000_000_007;
        int N = word.length();
        int[] count = new int[26];
        for (char c : word.toCharArray()) {
            count[c-'a']++;
        }
        int[][] dp = new int[26][N+1];
        for (int col = 1; col <= N; col++) {
            for (int i = 0; i < 26; i++) {
                dp[i][col] += dp[i][col-1];
            }
            for (int i = 0; i < 26; i++) {
                dp[i][col] = dp[i][col] + count[i];
            }
        }
        int countWonderful = 0;
        for (int i = 0; i < 26; i++) {
            countWonderful = (countWonderful + dp[i][N]) % MOD;
        }
        return countWonderful;
    }
}
