class Solution(object):
    def wordPattern(self, pattern, str):
        """
        :type pattern: str
        :type str: str
        :rtype: bool
        """
        mapping = dict()
        pattern_list = list(pattern)
        str_list = str.split(' ')
        if len(pattern_list)!= len(str_list):
            return False

        for i in range(len(str_list)):
            if str_list[i] in mapping.keys():
                if mapping[str_list[i]]!= pattern_list[i]:
                    return False
            else:
                if pattern_list[i] in mapping.values():
                    return False
                else:
                    mapping[str_list[i]] = pattern_list[i]
        return True

