func longestConsecutiveSequence(_ array: [Int]) -> [Int] {
    var result = [Int]()
    var map = Array(repeating: 0, count: array.count)
    for i in 0..<array.count {
        if map[i] == 0 {
            map[i] = 1
            var low = array[i]
            var high = array[i]
            while true {
                if map[low-1]!= 1 {
                    map[low-1] = 2
                    low = low - 1
                } else {
                    break
                }
            }
            while true {
                if map[high+1]!= 1 {
                    map[high+1] = 2
                    high = high + 1
                } else {
                    break
                }
            }
            for j in low...high {
                map[j] = 3
            }
        }
    }
    for i in 0..<array.count {
        if map[i] == 3 {
            result.append(array[i])
        }
    }
    return result
