def fibonacci(n):
    """
    Calculate the nth Fibonacci number.

    Args:
        n: The number to calculate the Fibonacci number for.

    Returns:
        The nth Fibonacci number.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 1
    return fibonacci(n-1) + fibonacci(n-2)

